Review this simplified diff:

func cacheKey(req Request) string {
    b, _ := json.Marshal(req)
    return sha256Hex(b)
}

func handle(req Request) Response {
    if entry := cache.Get(cacheKey(req)); entry != nil {
        return entry.Response
    }
    resp := upstream(req)
    cache.Set(cacheKey(req), resp, time.Hour)
    return resp
}

Assume req may contain request_id, timestamp, auth headers, tools, response_format, and stream.
